    if (!pacer || pacer.done || pacer.stopped || !Number.isFinite(pacer.last)) continue;
    if (!match.paused && (!pacer.remote || (pacer.ready && !pacer.held))) {
      pacer.acc += Math.max(0, wallNow - pacer.last) / 1000 * old;
    }
    pacer.last = wallNow;
